%[text] # **Vented Hydrogen Deflagration Experiments**
%[text] %[text:anchor:T_D5D49718] # Pressure Sensors Verification
%[text] 1-DPR = prepare data
%[text] 2-EDA = decide windows / inspect behaviour
%[text] 3-PSVA = calculate verification metrics
%%
%[text] # **Data Preparation (DPR)**
%[text] %[text:anchor:H_23C559C1] ## 1. Setup (Matlab Startup File)
%[text] %[text:anchor:H_1B29D089] This m-File code prepare the environment to provide access to auxiliary files and sub-folders.
%clear ; clc; close all;
format short eng
scriptRoot = fileparts(mfilename("fullpath"));
[projectRoot,AuxFcn_GS] = AuxFcn_Matlab_Startup_File_001;
auxRoot = fullfile(projectRoot, ...
    "3-Calculations-Files", "Matlab-Files", "Auxilliary_Functions");
mainFcnRoot = fullfile(projectRoot, ...
    "3-Calculations-Files", "Matlab-Files", "Main_Functions");
addpath(genpath(auxRoot));
addpath(genpath(mainFcnRoot));
set(groot, 'defaultTextInterpreter', 'latex', 'defaultAxesTickLabelInterpreter','latex', 'defaultLegendInterpreter','latex');
%%
%[text] ## **2. Load & Overview of Raw Data Verification**
%[text] ### **2.1 Load Metadata & Overview**
metadataRoot = fullfile(projectRoot, ...
    "2-Data", "RawData", "Pressure_Sensors_Verification", "Metadata");

psvMetadata = AuxFcn_ReadPSVMetadataOverview_001(metadataRoot);

sensorGroupOverviewTable = psvMetadata.sensorGroupOverviewTable;
sensorMappingTable = psvMetadata.sensorMappingTable;
verificationPlanOverviewTable = psvMetadata.verificationPlanOverviewTable;
verificationPlanTable = psvMetadata.verificationPlanTable;

sensorMappingDisplayTable = sensorMappingTable(:, ...
    {'GroupId','DAQ_System','LoadedDAQField','Format','DAQ_Channel', ...
    'SensorId','SerialNumber','Sensitivity_pC_per_bar','Range_bar', ...
    'MeasuredQuantity','Active'});
disp(sensorMappingDisplayTable); %[output:3e2fc1f3]
disp(verificationPlanTable); %[output:36d4b236]
%[text] ### Create DUMMY Data
dummyRoot = fullfile(projectRoot, ...
    "2-Data", "RawData", "DUMMY_Data", "Pressure_Sensors_Verification_DUMMY");

dummyTPC5OverviewTable = AuxFcn_GenerateDummyPSVTPC5_001( ...
    dummyRoot, psvMetadata, Fs_Hz=1000, Duration_s=10);
disp(dummyTPC5OverviewTable); %[output:0476e3a8]

dummyMF4OverviewTable = AuxFcn_GenerateDummyPSVMF4_001( ...
    dummyRoot, metadataRoot, Fs_Hz=1000, Duration_s=10);
disp(dummyMF4OverviewTable); %[output:436df2ca]
%%
%[text] ### **2.2 Create** PSV Data Structure 
%[text] (from metadata + plan)
PSV = AuxFcn_BuildEmptyPSVStructure_001(psvMetadata);
disp(PSV.overview); %[output:5d378323]
%%
%[text] ### **2.3 Load Raw Data Verification**
%[text] **PSV-G01 & PSV-G02**
% rawRoot = fullfile(projectRoot, ...
%     "2-Data", "RawData", "Pressure_Sensors_Verification");
rawRoot = dummyRoot;
PSV = AuxFcn_LoadPSVRawData_001(PSV, rawRoot);
psvLoadStatusTable = PSV.tables.loadStatus;
disp(psvLoadStatusTable); %[output:197ca6a7]
%[text] **PSV-G01-Ref & PSV-G02-Ref**
% rawRoot = fullfile(projectRoot, ...
%     "2-Data", "RawData", "Pressure_Sensors_Verification");
rawRoot = dummyRoot;
PSV = AuxFcn_LoadPSVReferenceValues_001(PSV, rawRoot);
psvReferenceValuesTable = PSV.tables.referenceValues;

psvReferenceDisplayTable = psvReferenceValuesTable(:, ...
    {'GroupId','PointId','ReferenceMean_bar','ReferenceStd_bar', ...
    'ReferenceMin_bar','ReferenceMax_bar','ReferenceN', 'ReferenceFile'});
disp(psvReferenceDisplayTable); %[output:3d3da44a]
%%
%[text] ## 2.4 Export Data 
convertedRoot = fullfile(projectRoot, ...
    "2-Data", "ConvertedData", "Pressure_Sensors_Verification");

if ~isfolder(convertedRoot)
    mkdir(convertedRoot);
end

psvMatFile = fullfile(convertedRoot, "PSV_converted_raw_v001.mat");

save(psvMatFile, "PSV", "-v7.3");

